import type { Request, Response } from "express";
import { verify } from "../users.js";

export function login(req: Request, res: Response) {
  const { email, password } = req.body ?? {};
  if (typeof email !== "string" || typeof password !== "string") {
    res.status(400).json({ error: "email and password are required" });
    return;
  }
  const user = verify(email, password);
  if (!user) {
    res.status(401).json({ error: "invalid credentials" });
    return;
  }
  res.json({ id: user.id, email: user.email });
}
import request from "supertest";
import { describe, expect, it } from "vitest";
import { createApp } from "../src/app.js";

describe("POST /login", () => {
  it("signs in with the right password", async () => {
    const res = await request(createApp())
      .post("/login")
      .send({ email: "ada@example.com", password: "correct horse" });
    expect(res.status).toBe(200);
    expect(res.body).toEqual({ id: "u_1", email: "ada@example.com" });
  });

  it("rejects a wrong password", async () => {
    const res = await request(createApp())
      .post("/login")
      .send({ email: "ada@example.com", password: "battery staple" });
    expect(res.status).toBe(401);
  });

  it("needs an email and a password", async () => {
    const res = await request(createApp()).post("/login").send({ email: "ada@example.com" });
    expect(res.status).toBe(400);
  });
});
