import { scryptSync, timingSafeEqual } from "node:crypto";

type User = { id: string; email: string; salt: string; hash: string };

function hashPassword(password: string, salt: string) {
  return scryptSync(password, salt, 32).toString("hex");
}

const users: User[] = [
  { id: "u_1", email: "ada@example.com", salt: "b3a1", hash: hashPassword("correct horse", "b3a1") },
];

export function verify(email: string, password: string): User | undefined {
  const user = users.find((u) => u.email === email);
  if (!user) return undefined;
  const given = Buffer.from(hashPassword(password, user.salt), "hex");
  return timingSafeEqual(given, Buffer.from(user.hash, "hex")) ? user : undefined;
}
